 {ticker:'AAOI',snapshotIds:['AAOI-CURRENT-2026-06-30','AAOI-TTM-2026-06-30'],periodEnd:'2026-06-30',filedAt:'2026-08-06',amount:129.142,currency:'USD',sourceUrl:'https://www.sec.gov/Archives/edgar/data/1158114/000143774926026278/aaoi20260630_10q.htm',sourceSection:'Balance sheet and Notes 11–12',message:'AAOI: per-share value withheld. Mapped debt of $58.915m omits $129.142m of separately reported convertible senior notes. Claim value, conversion/settlement and bank-acceptance financing treatment need an explicit claims bridge.'},
 {ticker:'GOOG',snapshotIds:['GOOG-CURRENT-2026-06-30','GOOG-TTM-2026-06-30'],periodEnd:'2026-06-30',filedAt:'2026-07-23',amount:18023,currency:'USD',sourceUrl:'https://www.sec.gov/Archives/edgar/data/1652044/000165204426000071/goog-20260630.htm',sourceSection:'Mandatory-convertible preferred stock and related additional paid-in capital',message:'GOOG: per-share value withheld. $18,023m of mandatory-convertible preferred stock and related additional paid-in capital is not included in the common-equity claims bridge. Dividends, conversion and capped-call treatment need an explicit claims bridge.'}
