export function currentClaimsEvidence(snapshot){return issues.filter(x=>x.ticker===snapshot?.ticker&&x.periodEnd===snapshot?.periodEnd&&x.snapshotIds.includes(snapshot?.raw?.id)).map(x=>({...x,snapshotIds:[...x.snapshotIds]}));}
